%dw 2.0
var jsonPayload = read(payload, "application/json")
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tns http://soap.web.calledweb.lovesoa.org/
---
{
    soapenv#Envelope: {
        soapenv#Header: {},
        soapenv#Body: {
            tns#searchMovies: {
                request: {
                    (filterName: jsonPayload.filters.name) if jsonPayload.filters.name?,
                    (filterGenre: jsonPayload.filters.genre) if jsonPayload.filters.genre?,
                    (filterMpaaRating: jsonPayload.filters.mpaaRating) if jsonPayload.filters.mpaaRating?,
                    (filterOscarsCountMin: jsonPayload.filters.oscarsCountMin) if jsonPayload.filters.oscarsCountMin?,
                    (filterOscarsCountMax: jsonPayload.filters.oscarsCountMax) if jsonPayload.filters.oscarsCountMax?,
                    (sortFields: jsonPayload.sort map ((item) -> item)) if jsonPayload.sort?,
                    page: jsonPayload.page default 0,
                    size: jsonPayload.size default 20
                }
            }
        }
    }
}
